  dialogues: [
    {
      id: 'academic-collocations-dialogue',
      title: 'A Conference Presentation Discussion',
      context: 'Two doctoral candidates discuss their research findings on economic development.',
      lines: [
        { speaker: 'Nodira', text: "Our research draws a distinction between short-term growth and sustainable development.", translation: "Tadqiqotimiz qisqa muddatli o'sish va barqaror rivojlanish o'rtasidagi farqni ko'rsatadi." },
        { speaker: 'Shahzod', text: "The empirical evidence lends support to the hypothesis that FDI drives innovation.", translation: "Empirik dalillar to'g'ridan-to'g'ri xorijiy investitsiyalar innovatsiyani rag'batlantiradi degan gipotezani qo'llab-quvvatlaydi." },
        { speaker: 'Nodira', text: "We must pay attention to the underlying assumptions in our theoretical framework.", translation: "Nazariy asosimizdagi asosiy taxminlarga e'tibor berishimiz kerak." },
        { speaker: 'Shahzod', text: "The findings have far-reaching implications for regional economic policy.", translation: "Topilmalar mintaqaviy iqtisodiy siyosat uchun keng qamrovli ta'sirga ega." },
        { speaker: 'Nodira', text: "We need to draw a comparison between our results and those of similar studies.", translation: "Natijalarimizni shunga o'xshash tadqiqotlar bilan taqqoslashimiz kerak." },
      ],
    },
  ],
